const listCreditCollections = `-- name: ListCreditCollections :many
WITH alloc AS (
    SELECT a.collection_id, SUM(CASE WHEN a.kind = 'allocate' THEN a.amount ELSE -a.amount END)::numeric AS allocated
    FROM collection_allocations a
    WHERE a.organization_id = $1
    GROUP BY a.collection_id
)
SELECT c.id, c.uuid, c.code, c.collection_date, c.branch_id, c.rental_id, c.reservation_id,
    (c.amount - c.refunded_amount - COALESCE(alloc.allocated, 0))::numeric AS unallocated
FROM collections c
LEFT JOIN alloc ON alloc.collection_id = c.id
WHERE c.organization_id = $1
  AND c.account_id = $2
  AND c.status <> 'void'
  AND c.purpose <> 'deposit'
  AND c.amount - c.refunded_amount - COALESCE(alloc.allocated, 0) > 0
  AND ($3::bigint[] IS NULL OR c.branch_id = ANY($3::bigint[]))
  AND ($4::bigint[] IS NULL OR c.id = ANY($4::bigint[]))
  AND (
    $5::bigint IS NULL
    OR c.rental_id = $5::bigint
    OR ($6::bigint IS NOT NULL AND c.reservation_id = $6::bigint)
  )
ORDER BY c.collection_date, c.id
`

type ListCreditCollectionsParams struct {
	OrganizationID int64       `json:"organization_id"`
	AccountID      int64       `json:"account_id"`
	BranchIds      []int64     `json:"branch_ids"`
	Ids            []int64     `json:"ids"`
	RentalID       pgtype.Int8 `json:"rental_id"`
	ReservationID  pgtype.Int8 `json:"reservation_id"`
}

type ListCreditCollectionsRow struct {
	ID             int64          `json:"id"`
	Uuid           uuid.UUID      `json:"uuid"`
	Code           string         `json:"code"`
	CollectionDate pgtype.Date    `json:"collection_date"`
	BranchID       pgtype.Int8    `json:"branch_id"`
	RentalID       pgtype.Int8    `json:"rental_id"`
	ReservationID  pgtype.Int8    `json:"reservation_id"`
	Unallocated    pgtype.Numeric `json:"unallocated"`
}

// Collections of an account with money left to allocate (the party's
// credit), oldest first. Deposits are not free credit.
func (q *Queries) ListCreditCollections(ctx context.Context, arg ListCreditCollectionsParams) ([]ListCreditCollectionsRow, error) {
	rows, err := q.db.Query(ctx, listCreditCollections,
		arg.OrganizationID,
		arg.AccountID,
		arg.BranchIds,
		arg.Ids,
		arg.RentalID,
		arg.ReservationID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListCreditCollectionsRow{}
	for rows.Next() {
		var i ListCreditCollectionsRow
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.Code,
			&i.CollectionDate,
			&i.BranchID,
			&i.RentalID,
			&i.ReservationID,
			&i.Unallocated,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

